import random
from itertools import permutations


class Node:
    __slots__ = ("val", "next")

    def __init__(self, val, nxt=None):
        self.val, self.next = val, nxt


class LinkedList:
    def __init__(self, vals=()):
        self.head = None
        tail = None
        for v in vals:
            n = Node(v)
            if tail is None:
                self.head = tail = n
            else:
                tail.next = n
                tail = n

    def to_list(self):
        out, cur = [], self.head
        while cur:
            out.append(cur.val)
            cur = cur.next
        return out

    def swap(self, x, y):
        """Swap the first nodes holding x and y by relinking, not by copying."""
        if x == y:
            return
        prev_x = prev_y = None
        cur_x = cur_y = None
        prev, cur = None, self.head
        while cur:
            if cur.val == x and cur_x is None:
                prev_x, cur_x = prev, cur
            elif cur.val == y and cur_y is None:
                prev_y, cur_y = prev, cur
            prev, cur = cur, cur.next
        if cur_x is None or cur_y is None:
            return
        if prev_x:
            prev_x.next = cur_y
        else:
            self.head = cur_y
        if prev_y:
            prev_y.next = cur_x
        else:
            self.head = cur_x
        cur_x.next, cur_y.next = cur_y.next, cur_x.next


ok = True
for n in range(1, 7):                       # every list length and every pair
    base = list(range(n))
    for i in range(n):
        for j in range(n):
            ll = LinkedList(base)
            ll.swap(i, j)
            want = base[:]
            want[i], want[j] = want[j], want[i]
            ok &= ll.to_list() == want
random.seed(0)
for _ in range(2000):                       # random lists, adjacent + head/tail cases
    n = random.randint(2, 12)
    base = random.sample(range(100), n)
    i, j = random.randrange(n), random.randrange(n)
    ll = LinkedList(base)
    ll.swap(base[i], base[j])
    want = base[:]
    want[i], want[j] = want[j], want[i]
    ok &= ll.to_list() == want
print("CHECK (all swaps correct incl. adjacent/head/tail/self: %s) vs (True)" % ok)

from fractions import Fraction as F
from functools import lru_cache

# V(r,b) = best win prob with r red, b black left; you must bet before the deck
# runs out (equivalently the last card is a forced bet).
import sys
sys.setrecursionlimit(10000)

@lru_cache(maxsize=None)
def V(r, b):
    if r == 0:
        return F(0)
    if b == 0:
        return F(1)
    n = r + b
    stop = F(r, n)
    go = F(r, n) * V(r - 1, b) + F(b, n) * V(r, b - 1)
    return max(stop, go)

full = V(26, 26)
same = all(V(r, b) == F(r, r + b) for r in range(1, 15) for b in range(0, 15))
print("CHECK (V(26,26)=%s, V(r,b)==r/(r+b) everywhere: %s) vs (1/2, True)"
      % (full, same))

from fractions import Fraction as F
from itertools import permutations
from math import factorial


def one_pass(a):
    a = list(a)
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            a[i], a[i + 1] = a[i + 1], a[i]
    return a


def two_larger_before(p):          # contains pattern 231 or 321
    return any(sum(1 for x in p[:k] if x > p[k]) >= 2 for k in range(len(p)))


def from_composition(comp):        # cycle each consecutive block's max to its front
    out, start = [], 1
    for L in comp:
        blk = list(range(start, start + L))
        out += [blk[-1]] + blk[:-1]
        start += L
    return tuple(out)


def compositions(n):
    if n == 0:
        yield ()
        return
    for first in range(1, n + 1):
        for rest in compositions(n - first):
            yield (first,) + rest


counts, pow2, char_ok, bij_ok = [], [], True, True
for n in range(1, 9):
    good = set()
    for p in permutations(range(1, n + 1)):
        s = one_pass(p) == sorted(p)
        if s:
            good.add(p)
        char_ok &= (s == (not two_larger_before(p)))
    counts.append(len(good))
    pow2.append(2 ** (n - 1))
    bij_ok &= {from_composition(c) for c in compositions(n)} == good
probs = [F(c, factorial(n + 1)) for n, c in enumerate(counts)]
print("CHECK (counts n=1..8: %s == 2^(n-1): %s, pattern characterisation: %s, "
      "composition bijection: %s, P for n=3..7: %s) vs (True, True, True, "
      "[2/3, 1/3, 2/15, 2/45, 4/315])"
      % (counts, counts == pow2, char_ok, bij_ok, [str(x) for x in probs[2:7]]))
